    }

    .projects {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 20px;
      margin-top: 20px;
    }

    .project-card {
      background: white;
      padding: 20px;
      border-radius: 10px;
      box-shadow: 0 0 10px gray;
    }

    .project-card img {
      max-width: 100%;
      border-radius: 10px;
    }
    .image-row {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 10px;
}

.image-row img {
  width: 100%;
  height: auto;
}
.row {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.description {
  width: 50%;
  padding: 20px;
  text-align: left;
}

.image {
  width: 50%;
  padding: 20px;
  text-align: right;
}

.image img {
  width: 60%;
  height: 40%;
}
